// ============================================================================
// RED-BLACK TREE IMPLEMENTATION
// ============================================================================
//
// A Red-Black Tree is a self-balancing binary search tree with the following
// invariants:
//   1. Every node is either red or black.
//   2. The root is black.
//   3. All leaves (NIL pointers) are black.
//   4. If a node is red, then both its children are black.
//   5. For each node, all paths from the node to descendant leaves contain
//      the same number of black nodes (black-height).
//
// These invariants guarantee that the tree is approximately balanced,
// ensuring O(log n) worst-case time complexity for insert, delete, and search.
//
// This implementation uses explicit parent pointers and a color enum for
// node state. Nil nodes are represented by nullptr with a virtual BLACK color.
//

namespace rbt {

// Color enumeration for red-black tree nodes.
// Using an enum class for type safety.
enum class Color {
    RED,   // Red nodes
    BLACK  // Black nodes
};

// Utility to get the opposite color (used in some rebalancing scenarios).
inline Color opposite(Color c) {
    return (c == Color::RED) ? Color::BLACK : Color::RED;
}

// String representation of color for debugging purposes.
inline const char* color_name(Color c) {
    switch (c) {
        case Color::RED:   return "RED";
        case Color::BLACK: return "BLACK";
        default:           return "UNKNOWN";
    }
}

